@section('content')<div class="page-heading"><div><span class="eyebrow">SALES</span><h1>Bill history</h1><p>Completed bills from your shop.</p></div><a href="{{ route('pos') }}" class="button primary">＋ Create new bill</a></div><section class="panel">@if($sales->isEmpty())<div class="empty-state"><div class="empty-icon">▤</div><b>No bills yet</b><p>Completed sales will be listed here.</p><a href="{{ route('pos') }}" class="button primary">Create a bill</a></div>@else<div class="table-wrap"><table><thead><tr><th>BILL</th><th>DATE & TIME</th><th>CREATED BY</th><th>ITEMS</th><th>PAYMENT</th><th>AMOUNT</th><th></th></tr></thead><tbody>@foreach($sales as $sale)<tr><td><a class="table-primary" href="{{ route('sales.receipt',$sale) }}?from=history">{{ $sale->bill_number }}</a></td><td>{{ $sale->sold_at->format('d M Y, h:i A') }}</td><td>{{ $sale->user?->name ?? 'Staff' }}</td><td>{{ $sale->items->sum('quantity') }}</td><td>{{ $sale->balance_due>0?'UDHAAR / PART PAID':($sale->payments->pluck('method')->unique()->map(fn($x)=>strtoupper($x))->join(', ')?:'UDHAAR') }}</td><td class="amount">₹{{ number_format($sale->total,2) }}</td><td><a class="text-link" href="{{ route('sales.receipt',$sale) }}?from=history">Receipt →</a></td></tr>@endforeach</tbody></table></div><div class="pagination">{{ $sales->links() }}</div>@endif</section>@endsection
